&__info {
  margin-top: var(--gutter-2xl);
  display: grid;
  grid-template-columns: 10fr 2fr;
  gap: var(--gutter-md);

  &-list {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: var(--gutter-sm);
