&--highlight {
  --corner-btn-color: var(--clr-text-title);
  --corner-btn-border: color-mix(
    in srgb,
    var(--clr-text-title) 48%,
    transparent
  );
  --corner-btn-bg:
    linear-gradient(
        180deg,
        color-mix(in srgb, var(--clr-text-title) 16%, transparent),
        color-mix(in srgb, var(--clr-text-title) 8%, transparent)
      )
      0 0 / 100% 100% no-repeat,
    linear-gradient(
        90deg,
        transparent 0%,
        color-mix(in srgb, var(--clr-text-title) 22%, transparent) 48%,
        transparent 100%
      ) -140%
      0 / 60% 100% no-repeat;
  --corner-btn-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--clr-text-title) 18%, transparent),
    0 0 0 1px color-mix(in srgb, var(--clr-text-title) 12%, transparent),
    0 0 fluid(20, 36)
      color-mix(in srgb, var(--clr-text-title) 22%, transparent);
  --corner-btn-corner: color-mix(
    in srgb,
    var(--clr-text-title) 72%,
    var(--clr-border-strong)
